import{_ as e,a,o as r,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Cart","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/cart/index.md","filePath":"api/graphql-api/shop/cart/index.md","lastUpdated":1786429091000}'),i={name:"api/graphql-api/shop/cart/index.md"};function d(n,t,h,c,p,s){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="cart" tabindex="-1">Cart <a class="header-anchor" href="#cart" aria-label="Permalink to &quot;Cart&quot;">​</a></h1><p>The Cart menu is the shopping cart — creating a cart, adding and updating items, applying coupons, and reading the current cart with its totals. It is the first half of the buying flow; once the cart is ready you move on to <a href="/api/graphql-api/shop/checkout/">Checkout</a>.</p><h2 id="how-the-cart-token-works" tabindex="-1">How the cart token works <a class="header-anchor" href="#how-the-cart-token-works" aria-label="Permalink to &quot;How the cart token works&quot;">​</a></h2><p>Creating a cart returns a <strong>cart token</strong>. That token identifies the cart on every subsequent cart operation, so a guest can build up a cart without being signed in. A signed-in customer can also keep a cart; the <strong>merge</strong> mutation combines a guest cart into the customer&#39;s cart after they log in, so nothing is lost.</p><h2 id="typical-sequence" tabindex="-1">Typical sequence <a class="header-anchor" href="#typical-sequence" aria-label="Permalink to &quot;Typical sequence&quot;">​</a></h2><ol><li>Create a cart, which returns the cart token.</li><li>Add items, updating or removing them as the shopper changes their mind.</li><li>Apply a coupon if the shopper has one, and remove it again if needed.</li><li>Read the cart at any point to show the current items and totals.</li></ol><p>A cart only exists once something has been added to it. Reading before the first item — or after the last one is removed — returns a <code>Cart not found</code> error rather than an empty cart.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>Create a cart</td><td><a href="/api/graphql-api/shop/mutations/create-cart.html"><code>createCartToken</code></a></td><td>Start a guest cart and return the token that identifies it.</td></tr><tr><td>Read the cart</td><td><a href="/api/graphql-api/shop/queries/get-cart.html"><code>createReadCart</code></a></td><td>The current cart with its items and totals. A mutation despite being a read.</td></tr><tr><td>Add an item</td><td><a href="/api/graphql-api/shop/mutations/add-to-cart.html"><code>createAddProductInCart</code></a></td><td>Add a product, including configurable, bundle, grouped, downloadable, and booking types.</td></tr><tr><td>Update quantity</td><td><a href="/api/graphql-api/shop/mutations/update-cart-item.html"><code>createUpdateCartItem</code></a></td><td>Change the quantity of one cart item.</td></tr><tr><td>Remove an item</td><td><a href="/api/graphql-api/shop/mutations/remove-cart-item.html"><code>createRemoveCartItem</code></a></td><td>Drop one item from the cart.</td></tr><tr><td>Merge carts</td><td><a href="/api/graphql-api/shop/mutations/merge-cart.html"><code>createMergeCart</code></a></td><td>Fold a guest cart into the customer&#39;s cart after login.</td></tr><tr><td>Upload a customizable file</td><td><a href="/api/graphql-api/shop/mutations/upload-customizable-file.html"><code>createAddProductInCart</code></a></td><td>Attach a file to a product&#39;s customizable option while adding it.</td></tr><tr><td>Apply a coupon</td><td><a href="/api/graphql-api/shop/mutations/apply-coupon.html"><code>createApplyCoupon</code></a></td><td>Apply a coupon code to the cart.</td></tr><tr><td>Remove a coupon</td><td><a href="/api/graphql-api/shop/mutations/remove-coupon.html"><code>createRemoveCoupon</code></a></td><td>Remove the applied coupon.</td></tr></tbody></table><p>Reading the cart is <code>createReadCart</code>, a mutation rather than a query — GraphQL clients that route reads and writes differently need to treat it as a write.</p><p>Cart operations are keyed by the cart token; a guest needs only the storefront key, while a signed-in customer also sends their Bearer token. See <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',11)]))}const m=e(i,[["render",d]]);export{u as __pageData,m as default};
